window.FLASHCARD_DATA = {"meta":{"title":"双语术语卡片数据集","version":"1.0","count":115},"categories":[{"id":"theory","name":"翻译理论与流派","nameEn":"Translation Theories","icon":"📚","color":"#6366f1"},{"id":"tech","name":"翻译技术与工具","nameEn":"Translation Technology","icon":"🛠️","color":"#06b6d4"},{"id":"industry","name":"翻译行业与职业","nameEn":"Industry \u0026 Career","icon":"💼","color":"#10b981"},{"id":"linguistics","name":"语言学与翻译","nameEn":"Linguistics","icon":"🔤","color":"#f59e0b"},{"id":"localization","name":"本地化与全球化","nameEn":"Localization","icon":"🌍","color":"#ec4899"},{"id":"written","name":"笔译术语","nameEn":"Written Translation","icon":"✍️","color":"#8b5cf6"},{"id":"interpretation","name":"口译术语","nameEn":"Interpretation","icon":"🎙️","color":"#ef4444"},{"id":"errors","name":"常见翻译错误","nameEn":"Common Errors","icon":"⚠️","color":"#f97316"}],"terms":[{"id":1,"front":"Faithfulness, Expressiveness and Elegance","term":"信达雅","pinyin":"Xìn Dá Yǎ","definition":"中国近代翻译家严复在《天演论·译例言》中提出的翻译标准。信指忠实于原文；达指译文通顺流畅；雅指译文典雅优美。这一标准对中国翻译理论发展影响深远。","definitionEn":"Yan Fu\u0027s three principles of translation proposed in the preface to his translation of \u0027Evolution and Ethics\u0027. Faithfulness (Xìn) means loyalty to the original; Expressiveness (Dá) means fluency in the target language; Elegance (Yǎ) means literary grace.","example":"优秀的文学翻译应该兼顾信达雅三个方面。","exampleEn":"Excellent literary translation should balance all three aspects: faithfulness, expressiveness, and elegance.","category":"theory","tags":["核心标准","中国传统","严复"]},{"id":2,"front":"Functional Equivalence","term":"功能对等","pinyin":"Gōngnéng Duìděng","definition":"尤金·奈达提出的翻译理论，强调译文在目标语读者中产生的反应应与原文在源语读者中产生的反应基本一致。分为最低功能对等和最高功能对等两个层次。","definitionEn":"Eugene Nida\u0027s translation theory emphasizing that the response of the target language reader to the translation should be essentially equivalent to the response of the source language reader to the original text.","example":"翻译广告标语时，功能对等比字面对等更重要。","exampleEn":"When translating advertising slogans, functional equivalence is more important than literal equivalence.","category":"theory","tags":["奈达","等效理论","读者反应"]},{"id":3,"front":"Formal Equivalence","term":"形式对等","pinyin":"Xíngshì Duìděng","definition":"与功能对等相对，强调译文在形式上尽量与原文保持一致，包括词汇、句法、语序等。又称动态对等的对立面，多用于宗教文本等强调形式的翻译。","definitionEn":"The counterpart of functional equivalence, emphasizing formal correspondence between source and target text, including vocabulary, syntax, and word order.","example":"某些宗教经典翻译追求形式对等以保留原文神圣性。","exampleEn":"Some religious scripture translations seek formal equivalence to preserve the sanctity of the original.","category":"theory","tags":["奈达","形式对应","直译"]},{"id":4,"front":"Skopos Theory","term":"目的论","pinyin":"Mùdì Lùn","definition":"德国功能翻译学派提出的理论，核心是\"翻译目的决定翻译方法\"。三大法则：目的法则（skopos rule）、连贯法则（coherence rule）、忠实法则（fidelity rule）。","definitionEn":"A functionalist translation theory from Germany stating that the purpose of translation determines the translation method. Three rules: skopos rule, coherence rule, and fidelity rule.","example":"根据目的论，产品说明书的翻译应以目标读者理解为首要目的。","exampleEn":"According to Skopos Theory, product manual translation should prioritize target reader comprehension.","category":"theory","tags":["功能翻译","赖斯","弗米尔"]},{"id":5,"front":"Polysystem Theory","term":"多元系统论","pinyin":"Duōyuán Xìtǒng Lùn","definition":"以色列学者伊塔玛·埃文-佐哈尔提出，认为文学翻译在目标语文学多元系统中的位置（中心或边缘）决定了翻译策略的选择。处于中心时倾向异化，处于边缘时倾向归化。","definitionEn":"Proposed by Itamar Even-Zohar, this theory posits that the position of translated literature in the target literary polysystem determines translation strategy—central position favors foreignization, peripheral favors domestication.","example":"多元系统论解释了为什么不同时期翻译策略会有变化。","exampleEn":"Polysystem Theory explains why translation strategies change across different periods.","category":"theory","tags":["佐哈尔","系统理论","文学翻译"]},{"id":6,"front":"Foreignization","term":"异化翻译","pinyin":"Yìhuà Fānyì","definition":" Venuti提出的策略，尽量保留原文的语言和文化差异，让读者感受到异质性。与归化相对，主张\"保留他者性\"。","definitionEn":"Lawrence Venuti\u0027s strategy of preserving source language and cultural differences, making the reader feel the \u0027foreignness\u0027 of the text.","example":"异化翻译保留了东方文学中独特的文化意象。","exampleEn":"Foreignization preserves unique cultural imagery in Eastern literature.","category":"theory","tags":["Venuti","直译","文化保留"]},{"id":7,"front":"Domestication","term":"归化翻译","pinyin":"Guīhuà Fānyì","definition":" Venuti提出的策略，将原文的文化差异转化为目标语读者熟悉的表达方式，使译文流畅自然，读起来像\"本土文本\"。","definitionEn":"Lawrence Venuti\u0027s strategy of adapting source cultural expressions to target language reader\u0027s familiar forms, making the translation read like a native text.","example":"归化翻译让西方读者更容易接受东方故事。","exampleEn":"Domestication makes Eastern stories more accessible to Western readers.","category":"theory","tags":["Venuti","意译","文化适配"]},{"id":8,"front":"Text Typology","term":"文本类型学","pinyin":"Wénběn Lèixíng Xué","definition":"凯瑟琳娜·赖斯提出，将文本分为信息型、表达型、操作型三类，不同类型文本应采用不同的翻译策略。是功能翻译理论的重要组成部分。","definitionEn":"Katharina Reiss\u0027s classification of texts into informative, expressive, and operative types, each requiring different translation strategies.","example":"按照文本类型学，科技文本以传递信息为首要目标。","exampleEn":"According to Text Typology, sci-tech texts prioritize information transmission.","category":"theory","tags":["赖斯","功能翻译","文本分类"]},{"id":9,"front":"Cultural Translation","term":"文化翻译","pinyin":"Wénhuà Fānyì","definition":"苏珊·巴斯奈特等提出的研究方向，关注翻译中的文化因素，认为翻译不仅是语言转换，更是文化转换。翻译过程中文化负载词的处理是核心问题。","definitionEn":"An approach by Susan Bassnett focusing on translation as cultural transfer, not just linguistic transfer. Handling culture-loaded words is central.","example":"诗词翻译需要深入理解两种文化才能传情达意。","exampleEn":"Poetry translation requires deep understanding of both cultures to convey meaning and emotion.","category":"theory","tags":["巴斯奈特","文化研究","符号学"]},{"id":10,"front":"Post-colonial Translation Theory","term":"后殖民翻译理论","pinyin":"Hòu Zhímín Fānyì Lǐlùn","definition":"关注殖民时期翻译如何作为权力工具，以及后殖民语境下翻译的文化抵抗和身份重建。代表人物：霍米·巴巴、特兰斯维迪。","definitionEn":"Examines how translation served as a tool of power in colonial times and its role in cultural resistance and identity reconstruction post-colonially.","example":"后殖民理论重新审视了《鲁宾逊漂流记》的翻译接受史。","exampleEn":"Post-colonial theory re-examines the translation reception history of Robinson Crusoe.","category":"theory","tags":["权力话语","身份建构","巴巴"]},{"id":11,"front":"Equivalence Theory","term":"对等理论","pinyin":"Duìděng Lǐlùn","definition":"翻译研究的核心理论之一，探讨源文本与目标文本之间的关系。包括雅各布森的三种对等（语音、形态、语义）、奈达的功能/形式对等、卡特福德的文本对等与形式对应等。","definitionEn":"A core translation theory exploring relationships between source and target texts, including Jakobson\u0027s three types (phonetic, morphological, semantic), Nida\u0027s functional/formal equivalence, and Catford\u0027s textual equivalence.","example":"对等理论是翻译质量评估的理论基础。","exampleEn":"Equivalence Theory is the theoretical foundation for translation quality assessment.","category":"theory","tags":["核心理论","奈达","卡特福德"]},{"id":12,"front":"Register Analysis","term":"语域分析","pinyin":"Yùyù Fēnxī","definition":"韩礼德系统功能语言学中的概念，指不同使用情境下的语言变体。翻译时需识别原文语域并在译文中保持相应的语域等级。","definitionEn":"From Halliday\u0027s Systemic Functional Linguistics: language variations according to context of use. Translators must identify and maintain register levels.","example":"法律文本的翻译需要保持高度正式的语域。","exampleEn":"Legal text translation requires maintaining a highly formal register.","category":"theory","tags":["韩礼德","系统功能语言学","语体"]},{"id":13,"front":"Discourse Analysis","term":"话语分析","pinyin":"Huàyǔ Fēnxī","definition":"研究超出句子层面的语言组织与使用。翻译中的话语分析关注衔接与连贯、主述结构、信息流动等，确保译文在话语层面的连贯。","definitionEn":"Study of language organization beyond the sentence level. In translation: focus on cohesion, coherence, theme-rheme structure, and information flow.","example":"话语分析帮助译者把握原文的整体逻辑结构。","exampleEn":"Discourse Analysis helps translators grasp the overall logical structure of the original.","category":"theory","tags":["连贯","衔接","语篇"]},{"id":14,"front":"Theme-Rheme Theory","term":"主述位理论","pinyin":"Zhǔshù Wèi Lǐlùn","definition":"布拉格学派提出的句子信息结构分析方法。主位（Theme）是已知/假定信息，述位（Rheme）是新信息。跨语言翻译时主述结构可能需要调整。","definitionEn":"Prague School\u0027s method of analyzing sentence information structure. Theme = given/assumed info; Rheme = new info.","example":"中英语序差异常表现为主述位结构的不同。","exampleEn":"Chinese-English word order differences often manifest as different Theme-Rheme structures.","category":"theory","tags":["布拉格学派","信息结构","语序"]},{"id":15,"front":"Hatim \u0026 Mason Model","term":"哈蒂姆-梅森模式","pinyin":"Hā Tīng - Méisēn Móshì","definition":"对话语进行三维分析的翻译质量评估框架：交际维度（意图）、语用维度（功能）、符号维度（形式）。","definitionEn":"Hatim \u0026 Mason\u0027s three-dimensional translation quality assessment framework: communicative, pragmatic, and semiotic dimensions.","example":"使用哈蒂姆-梅森模式可以系统评估译文的质量。","exampleEn":"The Hatim \u0026 Mason model enables systematic translation quality assessment.","category":"theory","tags":["质量评估","话语分析","三维模式"]},{"id":20,"front":"Computer-Assisted Translation (CAT)","term":"计算机辅助翻译","pinyin":"Jìsuànjī Fǔzhù Fānyì","definition":"利用计算机软件辅助人工翻译的技术统称。CAT工具与机器翻译不同，是辅助译员而非替代译员。核心技术包括翻译记忆、术语库、对齐等。","definitionEn":"Technology using computer software to assist human translators. CAT tools differ from MT—they assist rather than replace translators.","example":"现代职业译员几乎都使用CAT工具提高效率。","exampleEn":"Professional translators almost universally use CAT tools to boost efficiency.","category":"tech","tags":["CAT","效率工具","行业标准"]},{"id":21,"front":"Translation Memory (TM)","term":"翻译记忆","pinyin":"Fānyì Jìyì","definition":"CAT工具的核心功能，存储已翻译的源文本和对应译文的数据库。当遇到相同或相似文本时自动检索并推荐，避免重复翻译，保持译文一致性。","definitionEn":"Core CAT tool functionality: a database storing previously translated source-target pairs. Automatically retrieves and suggests matches for identical or similar text.","example":"翻译记忆库的积累可以大幅降低大型项目的成本。","exampleEn":"Accumulated translation memories can significantly reduce costs for large projects.","category":"tech","tags":["CAT核心","复用","一致性"]},{"id":22,"front":"Terminology Management System (TMS)","term":"术语管理系统","pinyin":"Shùyǔ Guǎnlǐ Xìtǒng","definition":"集中管理翻译项目中专业术语的工具。确保整个项目中术语使用的一致性，通常与CAT工具集成。可包含术语定义、词性、语法信息等。","definitionEn":"Tools for centralized management of terminology in translation projects, ensuring consistency across the entire project.","example":"科技公司需要建立完善的术语管理系统。","exampleEn":"Tech companies need well-developed terminology management systems.","category":"tech","tags":["术语库","一致性","企业级"]},{"id":23,"front":"Trados Studio","term":"Trados Studio","pinyin":"Trados Studio","definition":"全球市场份额最大的商业CAT工具，由SDL（现RWS）开发。支持翻译记忆、术语库、AutoSuggest、机器翻译集成等功能，是行业主流工具。","definitionEn":"Market-leading commercial CAT tool by RWS (formerly SDL). Supports translation memory, terminology, AutoSuggest, MT integration.","example":"很多翻译公司把Trados作为标准工作环境。","exampleEn":"Many translation agencies standardize on Trados as their working environment.","category":"tech","tags":["商业CAT","行业标准","RWS"]},{"id":24,"front":"Machine Translation (MT)","term":"机器翻译","pinyin":"Jīqì Fānyì","definition":"完全由计算机完成的自动翻译，不依赖人工。分为基于规则、基于统计、基于神经网络的不同阶段。与CAT不同，MT是全自动翻译。","definitionEn":"Fully automatic translation by computers without human intervention. Includes rule-based, statistical, and neural-based approaches.","example":"谷歌翻译和DeepL都是基于神经网络的机器翻译系统。","exampleEn":"Google Translate and DeepL are both neural machine translation systems.","category":"tech","tags":["自动翻译","AI","神经网络"]},{"id":25,"front":"SDLXLIFF","term":"SDLXLIFF","pinyin":"SDLXLIFF","definition":"Trados Studio使用的本地化交换文件格式，基于XLIFF标准扩展。支持CAT工具特有的翻译记忆匹配、锁定文本等功能。","definitionEn":"Trados\u0027s extended localization file format based on XLIFF standard, supporting TM matches, locked text, etc.","example":"SDLXLIFF文件是Trados工作流程中的核心文件格式。","exampleEn":"SDLXLIFF files are the core format in Trados workflows.","category":"tech","tags":["文件格式","XLIFF扩展","Trados"]},{"id":26,"front":"Neural Machine Translation (NMT)","term":"神经机器翻译","pinyin":"Shénjīng Jīqì Fānyì","definition":"基于深度神经网络的机器翻译方法，使用编码器-解码器架构（Encoder-Decoder）和注意力机制（Attention）。代表模型：Google Neural Machine Translation (GNMT)、DeepL等。","definitionEn":"Deep learning-based MT using Encoder-Decoder architecture and Attention mechanism. Examples: GNMT, DeepL.","example":"神经机器翻译在流利度上远优于传统统计机器翻译。","exampleEn":"Neural MT is far more fluent than traditional statistical MT.","category":"tech","tags":["深度学习","AI翻译","Attention"]},{"id":27,"front":"Post-Editing (PE)","term":"后编辑","pinyin":"Hòu Biānjí","definition":"对机器翻译输出进行人工修订以达到可用质量的过程。分为轻量后编辑（Light PE）和全量后编辑（Full PE）。是MTPE工作流的核心环节。","definitionEn":"Manual revision of MT output to achieve usable quality. Divided into Light PE and Full PE. Core of MTPE workflow.","example":"专业后编辑器每小时可处理数千字机器译文。","exampleEn":"Professional post-editors can process thousands of characters of MT output per hour.","category":"tech","tags":["MTPE","修订","效率"]},{"id":28,"front":"XLIFF","term":"XLIFF","pinyin":"XLIFF","definition":"XML Localisation Interchange File Format，行业标准的本地化交换文件格式。XML编码，被所有主流CAT工具支持。","definitionEn":"XML Localisation Interchange File Format—the industry-standard XML-based localization exchange format.","example":"XLIFF格式确保了不同CAT工具之间的互操作性。","exampleEn":"XLIFF format ensures interoperability among different CAT tools.","category":"tech","tags":["标准格式","XML","互操作"]},{"id":29,"front":"Translation Memory eXchange (TMX)","term":"TMX","pinyin":"TMX","definition":"翻译记忆交换格式，基于XML的开放标准。用于在不同CAT工具之间交换翻译记忆数据，是LISA组织制定的标准。","definitionEn":"XML-based open standard for exchanging translation memory data between different CAT tools, developed by LISA.","example":"使用TMX格式可以在Trados和MemoQ之间导入翻译记忆。","exampleEn":"TMX format enables importing translation memories between Trados and MemoQ.","category":"tech","tags":["TM交换","开放标准","LISA"]},{"id":30,"front":"Automatic Language Identification","term":"自动语言识别","pinyin":"Zìdòng Yǔyán Shíbié","definition":"计算机程序自动识别文本所属语言的技术。CAT工具、搜索引擎等广泛使用。常见方法：基于n-gram统计、基于神经网络等。","definitionEn":"Techniques for automatic identification of text language by computer programs.","example":"浏览器可以自动识别网页语言并建议翻译。","exampleEn":"Browsers can auto-detect webpage language and suggest translation.","category":"tech","tags":["自然语言处理","文本处理","语言检测"]},{"id":31,"front":"Pre-Editing","term":"预编辑","pinyin":"Yù Biānjí","definition":"在使用机器翻译之前对源文本进行的优化处理。包括简化句子结构、消除歧义、统一术语等，可以显著提升机器翻译质量。","definitionEn":"Optimization of source text before MT: simplifying structure, eliminating ambiguity, unifying terminology to improve MT quality.","example":"技术文档在送MT前通常需要预编辑以保证翻译质量。","exampleEn":"Technical documents usually need pre-editing before MT to ensure translation quality.","category":"tech","tags":["MT优化","源文本","质量提升"]},{"id":32,"front":"Quality Assurance Checks (QA)","term":"质量保证检查","pinyin":"Zhìliàng Bǎozhèng Jiǎnchá","definition":"CAT工具内置的自动化检查功能，包括未翻译文本、数字一致性、标签完整性、术语一致性、标点符号错误、长度限制等。","definitionEn":"Automated CAT tool checks for untranslated segments, number consistency, tag integrity, terminology consistency, punctuation errors, length limits, etc.","example":"提交译文前必须通过CAT工具的所有QA检查。","exampleEn":"All QA checks in CAT tools must pass before delivery.","category":"tech","tags":["自动检查","质量控制","CAT功能"]},{"id":33,"front":"Text Alignment","term":"文本对齐","pinyin":"Wénběn Duìqí","definition":"将原文和译文按句段、段落或概念单元进行对应匹配的过程。可用于构建翻译记忆库。计算机辅助对齐工具：Trados WinAlign、LF Aligner等。","definitionEn":"Matching source and target text by segments, sentences, or units to build translation memories.","example":"老项目的文档可以通过文本对齐来创建翻译记忆。","exampleEn":"Legacy project documents can be aligned to build translation memories.","category":"tech","tags":["TM构建","双语平行","句段匹配"]},{"id":34,"front":"Translation Quality Evaluation","term":"翻译质量评估","pinyin":"Fānyì Zhìliàng Pínggū","definition":"评估译文质量的过程。分为人工评估（评分量表如MQM、TAUS DQF）和自动评估（BLEU、TER、COMET等指标）。","definitionEn":"Assessment of translation quality. Includes manual evaluation scales (MQM, TAUS DQF) and automatic metrics (BLEU, TER, COMET).","example":"BLEU分数是机器翻译常用的自动评估指标。","exampleEn":"BLEU score is a commonly used automatic MT evaluation metric.","category":"tech","tags":["质量评估","BLEU","MQM"]},{"id":35,"front":"Bilingual Corpus","term":"双语语料库","pinyin":"Shuāngyǔ Yǔliàokù","definition":"包含两种或多种语言文本及其对应翻译的数据库。分为平行语料库和可比语料库。用于翻译研究、机器翻译训练、翻译记忆等。","definitionEn":"Database containing texts in two+ languages with corresponding translations. Includes parallel and comparable corpora.","example":"联合国文件是构建中英平行语料库的重要来源。","exampleEn":"UN documents are an important source for building Chinese-English parallel corpora.","category":"tech","tags":["平行语料","可比语料","语料库语言学"]},{"id":36,"front":"Parallel Corpus","term":"平行语料库","pinyin":"Píngxíng Yǔliàokù","definition":"原文与译文一一对应的双语语料库。常用于训练机器翻译模型。如Europarl、UNPC、CWMT等公开资源。","definitionEn":"Bilingual corpora where source and target texts correspond one-to-one. Used to train MT models.","example":"CWMT平行语料库是中英机器翻译研究的重要资源。","exampleEn":"CWMT parallel corpus is an important resource for Chinese-English MT research.","category":"tech","tags":["一一对应","MT训练","公开资源"]},{"id":37,"front":"Comparable Corpus","term":"可比语料库","pinyin":"Kěbǐ Yǔliàokù","definition":"两种语言主题相似但不是互译的语料库。可用于挖掘翻译等价对、术语抽取等。如不同语言的新闻网站语料。","definitionEn":"Bilingual corpora with texts on similar topics but not translations of each other.","example":"可比语料库帮助发现专业领域的翻译等价对。","exampleEn":"Comparable corpora help discover translation equivalents in specialized fields.","category":"tech","tags":["主题相似","术语抽取","挖掘"]},{"id":38,"front":"BLEU","term":"BLEU","pinyin":"BLEU","definition":"Bilingual Evaluation Understudy，Papineni等(2002)提出的机器翻译自动评估指标。基于n-gram精确度计算，数值在0-100之间，越高越好。","definitionEn":"Papineni et al.\u0027s automatic MT metric based on n-gram precision scores (0-100, higher is better).","example":"BLEU 40分以上的机器翻译通常被认为质量不错。","exampleEn":"MT with BLEU score above 40 is generally considered good quality.","category":"tech","tags":["自动评估","n-gram","MT指标"]},{"id":39,"front":"Translation Edit Rate (TER)","term":"TER","pinyin":"TER","definition":"翻译编辑率，衡量将机器译文修改为参考译文所需的编辑操作比例。越低越好，编辑率为0表示译文完美。","definitionEn":"Translation Edit Rate measures the proportion of edits needed to change MT output into reference translation.","example":"TER指标与译员后编辑工作量高度相关。","exampleEn":"TER highly correlates with post-editing workload.","category":"tech","tags":["编辑距离","后编辑","MT评估"]},{"id":40,"front":"AutoSuggest","term":"AutoSuggest","pinyin":"AutoSuggest","definition":"Trados Studio的智能自动建议功能，基于翻译记忆、术语库、机器翻译、子段匹配等多种来源为译员实时提供建议。","definitionEn":"Trados Studio\u0027s intelligent suggestion feature drawing from TM, terminology, MT, subsegment matches.","example":"AutoSuggest可以显著加快高频文本的翻译速度。","exampleEn":"AutoSuggest significantly speeds up translation of repetitive text.","category":"tech","tags":["Trados功能","智能建议","效率提升"]},{"id":50,"front":"Localization (L10n)","term":"本地化","pinyin":"Běndìhuà","definition":"将产品（软件、网站、文档等）调整为适合特定目标市场语言和文化的过程。翻译是本地化的组成部分，但本地化还包括文化适配、格式调整等。","definitionEn":"Adapting products for specific target markets. Translation is part of localization, which also includes cultural adaptation, format adjustments.","example":"游戏本地化不仅要翻译文本，还要调整游戏机制和文化元素。","exampleEn":"Game localization involves more than just translating text—game mechanics and cultural elements must also be adjusted.","category":"industry","tags":["L10n","软件/网站","文化适配"]},{"id":51,"front":"Internationalization (I18n)","term":"国际化","pinyin":"Guójìhuà","definition":"在产品设计阶段预留多语言支持能力的过程。包括使用Unicode、从代码中提取硬编码文本、支持从右到左的语言等。为后续本地化做准备。","definitionEn":"Designing products to support multiple languages from the start. Preparation step before localization.","example":"好的国际化设计可以大大降低后续本地化的成本。","exampleEn":"Good i18n design greatly reduces subsequent localization costs.","category":"industry","tags":["I18n","软件设计","技术准备"]},{"id":52,"front":"Globalization (G11n)","term":"全球化","pinyin":"Quánqiúhuà","definition":"I18n + L10n的总和，即同时进行国际化设计和本地化适配的完整过程。也指产品面向全球市场的整体战略。","definitionEn":"The combined process of internationalization and localization, or the overall strategy for global markets.","example":"全球化产品需要先做国际化再做各地的本地化。","exampleEn":"Global products need internationalization first, then localization for each market.","category":"industry","tags":["G11n","完整流程","全球战略"]},{"id":53,"front":"Language Service Provider (LSP)","term":"翻译服务提供商","pinyin":"Fānyì Fúwù Tígōng Shāng","definition":"提供翻译、本地化、多语言内容服务的公司或组织。大型LSP通常提供项目管理、技术工具、质量保证等一站式服务。","definitionEn":"Companies providing translation, localization, and multilingual content services.","example":"世界上最大的LSP如Lionbridge、TransPerfect年收入超过十亿美元。","exampleEn":"World\u0027s largest LSPs like Lionbridge and TransPerfect earn over a billion dollars annually.","category":"industry","tags":["LSP","外包","行业"]},{"id":54,"front":"Translator","term":"译员","pinyin":"Yìyuán","definition":"从事翻译工作的专业人员。需具备源语言和目标语言的精通能力、跨文化沟通能力、专业领域知识等。分为笔译译员和口译译员。","definitionEn":"Professional engaged in translation, requiring mastery of source and target languages, cultural competence, and domain knowledge.","example":"好的译员不仅双语精通，还需要有特定领域的专业知识。","exampleEn":"Good translators need not only bilingual mastery but also domain expertise.","category":"industry","tags":["职业","双语","专业能力"]},{"id":55,"front":"Freelance Translator","term":"自由译员","pinyin":"Zìyóu Yìyuán","definition":"独立工作的翻译从业者，不隶属于任何特定翻译公司。通常通过ProZ、TranslatorsCafe等平台接单。需要自行管理客户关系、税务、营销等。","definitionEn":"Independent translators working for themselves, usually finding work through platforms like ProZ or TranslatorsCafe.","example":"自由译员需要同时管理翻译工作和自己的小生意。","exampleEn":"Freelance translators must manage both translation work and their own small business.","category":"industry","tags":["独立职业","平台","自雇"]},{"id":56,"front":"Project Manager (PM)","term":"项目经理","pinyin":"Xiàngmù Jīnlǐ","definition":"翻译公司中负责协调翻译项目的人员。工作内容包括项目启动、资源调配、进度监控、质量把控、客户沟通、项目收尾等。","definitionEn":"Staff at translation agencies coordinating projects: initiation, resource allocation, progress tracking, quality, client communication.","example":"好的项目经理能让大型多语言项目顺利交付。","exampleEn":"Skilled project managers enable smooth delivery of large multilingual projects.","category":"industry","tags":["项目协调","流程管理","团队"]},{"id":57,"front":"Proofreading","term":"校对","pinyin":"Xiàoduì","definition":"对译好的文本进行最终检查的环节，主要检查拼写、语法、标点、格式等语言层面的错误，确保译稿交付质量。通常是翻译流程的最后一步。","definitionEn":"Final checking of translated text for spelling, grammar, punctuation, formatting errors—the last step in the translation process.","example":"校对者需要比译员更注重细节和语言规范。","exampleEn":"Proofreaders need even more attention to detail and language norms than translators.","category":"industry","tags":["质量把关","最终检查","语言规范"]},{"id":58,"front":"Editing","term":"编辑","pinyin":"Biānjí","definition":"对译文进行内容层面的审查和改进。不仅仅检查错误，还可以优化措辞、调整风格、增强可读性。通常由母语为目标语言的专业人士进行。","definitionEn":"Content-level review and improvement of translations: optimizing wording, style, readability, not just error-checking.","example":"编辑环节能让机器翻译的生硬输出变得通顺自然。","exampleEn":"Editing can make stiff MT output flow naturally.","category":"industry","tags":["内容优化","风格","母语者"]},{"id":59,"front":"Review","term":"审校","pinyin":"Shěnjiào","definition":"译后审校环节，通常指由资深译员或领域专家对译文进行审核。比校对更侧重内容准确性，可能涉及回译、与原文对照等。","definitionEn":"Post-translation review by senior translators or domain experts, focusing on content accuracy.","example":"法律翻译必须经过资深译员的审校才能交付。","exampleEn":"Legal translations must pass senior reviewer approval before delivery.","category":"industry","tags":["审核","资深","准确性"]},{"id":60,"front":"Four-Eyes Principle","term":"四级校对","pinyin":"Sìjí Xiàoduì","definition":"德国标准DIN 2345中规定的翻译质量标准，要求译文必须由两名有资质的译员进行独立审校后才能交付。即\"四只眼睛看同一篇译文\"。","definitionEn":"DIN 2345 standard requiring two qualified translators to independently review a translation before delivery.","example":"医药翻译公司通常采用四级校对原则确保质量。","exampleEn":"Medical translation firms typically use the four-eyes principle to ensure quality.","category":"industry","tags":["德国标准","双重审校","质量保证"]},{"id":61,"front":"Translation Memory Ownership","term":"翻译记忆库所有权","pinyin":"Fānyì Jìyìkù Suǒyǒuquán","definition":"关于客户、翻译公司、译员之间谁拥有翻译记忆库数据的法律和商业问题。通常客户付费项目产生的TM归客户所有，但具体归属需在合同中约定。","definitionEn":"Legal and commercial questions about who owns TM data among clients, agencies, and translators.","example":"自由译员签订合同时要注意翻译记忆库所有权条款。","exampleEn":"Freelance translators should pay attention to TM ownership clauses in contracts.","category":"industry","tags":["法律问题","合同条款","知识产权"]},{"id":62,"front":"Non-Disclosure Agreement (NDA)","term":"保密协议","pinyin":"Bǎomì Xiéyì","definition":"译员与客户签订的法律协议，禁止译员披露翻译项目中的任何保密信息。翻译合同通常包含NDA条款。","definitionEn":"Legal agreement between translator and client prohibiting disclosure of confidential project information.","example":"翻译未上映的电影字幕前必须签署保密协议。","exampleEn":"An NDA must be signed before translating unreleased movie subtitles.","category":"industry","tags":["法律","合同","商业机密"]},{"id":63,"front":"Translation Rates","term":"费率","pinyin":"Fèilǜ","definition":"翻译服务的定价方式。常见有按字数/词数计费（最常见）、按每小时计费、按每页计费、按项目计费等。费率因语言对、领域、方向、译员资历等差异巨大。","definitionEn":"Pricing for translation services: per word/character (most common), per hour, per page, or per project.","example":"中英翻译的市场价通常是每千字150-300元人民币。","exampleEn":"Market rate for English-Chinese translation is typically 150-300 RMB per thousand characters.","category":"industry","tags":["定价","计费","市场"]},{"id":64,"front":"ProZ","term":"ProZ","pinyin":"ProZ","definition":"全球最大的翻译行业在线社区和外包平台。译员可以在此创建简历、参加翻译比赛、寻找工作、建立专业人脉。","definitionEn":"World\u0027s largest online translation industry community and outsourcing platform.","example":"很多自由译员通过ProZ获取大部分工作机会。","exampleEn":"Many freelance translators get most of their work through ProZ.","category":"industry","tags":["平台","社区","自由译员"]},{"id":65,"front":"Translation Agency","term":"翻译公司","pinyin":"Fānyì Gōngsī","definition":"专门提供翻译服务的企业实体。通常承接企业客户的翻译项目，将工作分派给内部或外部译员，负责项目管理和质量控制。","definitionEn":"Business entities providing translation services, managing projects and quality for corporate clients.","example":"大型跨国公司通常与翻译公司签订长期合作协议。","exampleEn":"Large multinationals typically sign long-term agreements with translation agencies.","category":"industry","tags":["LSP","外包","项目管理"]},{"id":70,"front":"Source Language (SL)","term":"源语言","pinyin":"Yuányǔyán","definition":"翻译中被翻译的语言。如将中文翻译成英文，则中文是源语言，英文是目标语言。","definitionEn":"The language being translated from.","example":"在中英翻译项目中，中文是源语言。","exampleEn":"In Chinese-to-English translation projects, Chinese is the source language.","category":"linguistics","tags":["基础概念","翻译方向","SL"]},{"id":71,"front":"Target Language (TL)","term":"目标语言","pinyin":"Mùbiāo Yǔyán","definition":"翻译的产出语言。如将中文翻译成英文，则英文是目标语言。","definitionEn":"The language being translated into.","example":"作为目标语言的译文应该自然流畅。","exampleEn":"Translations in the target language should be natural and fluent.","category":"linguistics","tags":["基础概念","翻译方向","TL"]},{"id":72,"front":"Into Foreign Language","term":"外语译入","pinyin":"Wàiyǔ Yìrù","definition":"译入非母语。如中文母语者将英文翻译成中文（译入母语）是主流方向，但翻译成其他外语（如日语、法语）则是外语译入。","definitionEn":"Translating into a non-native language.","example":"外语译入对译员的目标语言能力要求极高。","exampleEn":"Translating into a foreign language requires extremely high target language competence.","category":"linguistics","tags":["翻译方向","非母语","难度高"]},{"id":73,"front":"Into Mother Tongue","term":"母语译入","pinyin":"Mǔyǔ Yìrù","definition":"译入母语。如中文母语者将英文翻译成中文。这是翻译的主要方向，因为译员对母语的掌握更娴熟。","definitionEn":"Translating into one\u0027s native language—the primary direction, as translators have better mastery of their native tongue.","example":"大多数翻译公司只接受母语译入的译员。","exampleEn":"Most translation agencies only hire translators who translate into their mother tongue.","category":"linguistics","tags":["翻译方向","母语","主流"]},{"id":74,"front":"Pragmatics","term":"语用学","pinyin":"Yǔyòngxué","definition":"研究语言在特定语境中的使用和意义的语言学分支。翻译中的语用问题包括暗示、双关、礼貌、讽刺等，需要考虑语境和意图。","definitionEn":"Study of language use and meaning in context. Deals with implicature, puns, politeness, irony in translation.","example":"翻译双关语需要同时考虑语义和语用两个层面。","exampleEn":"Translating puns requires considering both semantic and pragmatic levels.","category":"linguistics","tags":["语境","意义","隐含"]},{"id":75,"front":"Semantics","term":"语义学","pinyin":"Yǔyìxué","definition":"研究语言意义的语言学分支。翻译中语义学关注词汇意义、句子意义、命题意义等，确保译文不改变原文的基本语义内容。","definitionEn":"Linguistic branch studying meaning. In translation: lexical, sentential, propositional meaning.","example":"翻译的基础是保持原文的语义不变。","exampleEn":"The foundation of translation is preserving the source text\u0027s semantics.","category":"linguistics","tags":["意义","词汇","命题"]},{"id":76,"front":"Syntax","term":"句法","pinyin":"Jùfǎ","definition":"研究句子结构的语言学分支。不同语言的句法差异很大，如中文重意合、英文重形合，翻译时需要进行句法结构的转换。","definitionEn":"Study of sentence structure. Chinese emphasizes parataxis while English emphasizes hypotaxis.","example":"中译英时通常需要把中文的流水句改造成英文的复合句。","exampleEn":"Chinese-to-English translation often converts paratactic sentences to hypotactic ones.","category":"linguistics","tags":["句子结构","意合/形合","差异"]},{"id":77,"front":"Lexicology","term":"词汇学","pinyin":"Cíhuìxué","definition":"研究词汇的语言学分支，包括词义、词源、构词法、词汇关系等。翻译中词汇选择是最基础也最关键的环节。","definitionEn":"Linguistic branch studying vocabulary: word meaning, etymology, word formation, lexical relations.","example":"好的翻译需要在丰富的词汇中做出精准选择。","exampleEn":"Good translation requires precise choices from a rich vocabulary.","category":"linguistics","tags":["词汇","词义","选词"]},{"id":78,"front":"Parataxis","term":"意合","pinyin":"Yìhé","definition":"靠语义连接而非语言形式连接的句子组织方式。典型如中文，多个分句可以通过语义自然衔接而不需要显性的连接词。","definitionEn":"Sentence organization through semantic rather than formal connections—typical of Chinese.","example":"中文的意合特点使得中译英时需要补充逻辑连接词。","exampleEn":"Chinese parataxis means logical connectors must often be added in C-E translation.","category":"linguistics","tags":["中文特点","语义连接","无显性连接"]},{"id":79,"front":"Hypotaxis","term":"形合","pinyin":"Xínghé","definition":"靠显性的语法手段（连接词、介词、关系代词等）连接句子成分的组织方式。典型如英文，句子结构有严格的语法框架。","definitionEn":"Sentence organization through explicit grammatical markers (connectors, prepositions, relative pronouns)—typical of English.","example":"英文的形合特点意味着英译中时可以适当减少连接词。","exampleEn":"English hypotaxis means connectors can often be reduced in E-C translation.","category":"linguistics","tags":["英文特点","语法连接","显性标记"]},{"id":80,"front":"Semantic Field","term":"语义场","pinyin":"Yǔyì Chǎng","definition":"一组在语义上相互关联的词构成的词汇系统。翻译中理解不同语言的语义场差异有助于准确选词。","definitionEn":"Group of semantically related words forming a lexical system.","example":"中英颜色词的语义场划分并不完全一致。","exampleEn":"The semantic field of color terms differs between Chinese and English.","category":"linguistics","tags":["词汇系统","词群","对比"]},{"id":81,"front":"Hyponymy","term":"上下义关系","pinyin":"Shàngxiàyì Guānxì","definition":"词汇之间的包含关系。上义词（superordinate）表示更概括的概念，下义词（hyponym）表示更具体的概念。翻译中选择上义词还是下义词影响精确度。","definitionEn":"Inclusion relationship between words. Choosing superordinate vs hyponym affects precision in translation.","example":"\"花卉\"是\"玫瑰\"、\"百合\"等的上义词。","exampleEn":"\"Flower\" is the superordinate of \"rose\", \"lily\", etc.","category":"linguistics","tags":["词汇关系","概括/具体","精确度"]},{"id":82,"front":"Componential Analysis","term":"语义成分分析","pinyin":"Yǔyì Chéngfèn Fēnxī","definition":"将一个词的语义分解为若干最小的语义特征（如[+有生命]、[+男性]、[-成年]）的方法。用于对比不同语言词汇的语义异同。","definitionEn":"Breaking word meaning into minimal semantic features like [+animate], [+male], [-adult].","example":"\"boy\"和\"lad\"的语义成分高度重叠但不完全相同。","exampleEn":"The components of \"boy\" and \"lad\" overlap but are not identical.","category":"linguistics","tags":["语义分解","特征","对比"]},{"id":83,"front":"Equivalent","term":"等值词","pinyin":"Děngzhící","definition":"源语言和目标语言中语义功能相同的词或短语。分为完全等值词和部分等值词。完全等值词极少，多数是部分等值。","definitionEn":"Words/phrases with the same semantic function in source and target languages.","example":"中文\"咖啡\"与英文\"coffee\"是完全等值词。","exampleEn":"Chinese \"kāfēi\" and English \"coffee\" are complete equivalents.","category":"linguistics","tags":["词汇对等","翻译单位","语义"]},{"id":84,"front":"Partial Equivalent","term":"不完全等值词","pinyin":"Bù Wánquán Děngzhící","definition":"只在部分语义上重叠的等值词。如中文的\"老师\"可以对应英文的\"teacher\"，但\"老师\"还有\"师傅\"、\"先生\"等其他含义。","definitionEn":"Equivalents that only partially overlap in meaning.","example":"中文\"老师\"与英文\"teacher\"是不完全等值词。","exampleEn":"Chinese \"lǎoshī\" and English \"teacher\" are partial equivalents.","category":"linguistics","tags":["词汇差异","多义","部分重叠"]},{"id":85,"front":"Zero Equivalent","term":"无等值词","pinyin":"Wú Děngzhící","definition":"目标语言中完全不存在对应概念的词。如中文的\"阴阳\"、\"道\"在英文中无直接对应，只能音译或释义。","definitionEn":"Words with no corresponding concept in the target language.","example":"中文\"功夫\"、\"饺子\"在英文中是零等值词，通常音译。","exampleEn":"Chinese \"gōngfu\" and \"jiǎozi\" have zero equivalents in English and are usually transliterated.","category":"linguistics","tags":["文化空缺","音译","外来词"]},{"id":86,"front":"Culture-Loaded Word","term":"文化负载词","pinyin":"Wénhuà Fùzǎicí","definition":"蕴含特定文化内涵的词汇。包括历史典故、风俗习惯、宗教信仰、地理特征等。是翻译中的难点，处理方式包括保留、替换、释义、音译等。","definitionEn":"Words carrying specific cultural connotations: historical allusions, customs, religion, geography.","example":"中秋节、龙舟节等文化负载词的翻译需要适当解释。","exampleEn":"Culture-loaded words like Mid-Autumn Festival often need appropriate explanation in translation.","category":"linguistics","tags":["文化","翻译难点","处理策略"]},{"id":87,"front":"Sociolinguistics","term":"社会语言学","pinyin":"Shèhuì Yǔyánxué","definition":"研究语言与社会关系的学科。翻译中社会语言学关注语言变体（方言、语体）、称呼语、敬语等的跨语言对等。","definitionEn":"Study of language-society relations. In translation: dialects, registers, address terms, honorifics.","example":"中文的称呼体系在翻译时需要找到合适的社会语言学对等。","exampleEn":"Chinese address term systems require appropriate sociolinguistic equivalents.","category":"linguistics","tags":["社会因素","称呼语","变体"]},{"id":88,"front":"Cognitive Linguistics","term":"认知语言学","pinyin":"Rènzhī Yǔyánxué","definition":"研究语言与认知关系的学科。翻译的认知语言学研究关注翻译过程中的思维活动、隐喻映射、概念整合等。","definitionEn":"Study of language-cognition relations. In translation: mental processes, metaphor mapping, conceptual blending.","example":"认知语言学解释了为什么某些翻译策略更自然。","exampleEn":"Cognitive linguistics explains why certain translation strategies feel more natural.","category":"linguistics","tags":["认知","隐喻","思维"]},{"id":100,"front":"UI Text Translation","term":"UI文本翻译","pinyin":"UI Wénběn Fānyì","definition":"软件用户界面（User Interface）中的文本翻译。按钮、菜单、标签、提示语等。需考虑UI空间限制、术语一致性、本地化适配等。","definitionEn":"Translating software user interface text: buttons, menus, labels, tooltips.","example":"UI文本翻译要特别注意文本长度变化对布局的影响。","exampleEn":"UI text translation must pay special attention to length changes affecting layout.","category":"localization","tags":["软件","界面","UI"]},{"id":101,"front":"Software Localization","term":"软件本地化","pinyin":"Ruǎnjiàn Běndìhuà","definition":"将软件产品适配到特定语言市场的完整过程。包括UI翻译、文档翻译、文化适配、功能调整、测试等。是全球化产品发布的关键环节。","definitionEn":"Complete adaptation of software to a specific language market: UI translation, docs, cultural adaptation, testing.","example":"微软Office的本地化覆盖了超过100种语言。","exampleEn":"Microsoft Office is localized into over 100 languages.","category":"localization","tags":["软件","L10n","产品发布"]},{"id":102,"front":"Internationalization Design","term":"国际化设计","pinyin":"Guójìhuà Shèjì","definition":"在产品设计阶段考虑多语言支持的设计原则。原则包括：文本外部化、避免嵌入硬编码、使用Unicode、支持多文本方向（LTR/RTL）、使用标准日期时间格式等。","definitionEn":"Design principles considering multilingual support: externalize text, Unicode, RTL support, standard date/time formats.","example":"国际化设计能让产品轻松支持阿拉伯语等RTL语言。","exampleEn":"Good i18n design enables easy support for RTL languages like Arabic.","category":"localization","tags":["I18n","设计原则","RTL"]},{"id":103,"front":"Localization Testing","term":"本地化测试","pinyin":"Běndìhuà Cèshì","definition":"验证本地化产品是否正常工作的测试过程。包括语言质量测试（LQA）、UI验证、功能测试、兼容性测试等。通常由母语者进行。","definitionEn":"Testing localized products: linguistic quality, UI verification, functionality, compatibility.","example":"游戏本地化测试需要检查文本是否超出按钮边界。","exampleEn":"Game localization testing must check if text exceeds button boundaries.","category":"localization","tags":["测试","LQA","质量验证"]},{"id":104,"front":"Double Expansion","term":"双扩展","pinyin":"Shuāng Kuòzhǎn","definition":"UI本地化时英文到目标语言文本长度增加的现象。某些语言（如德语、俄语）平均比英文长30-50%，阿拉伯语甚至可能翻倍。设计时需预留空间。","definitionEn":"UI text length expansion when translating from English. Some languages (German, Russian) are 30-50% longer.","example":"德语通常比英语长30%，UI设计需要考虑双扩展。","exampleEn":"German is typically 30% longer than English—double expansion must be considered in UI design.","category":"localization","tags":["UI","长度变化","空间预留"]},{"id":105,"front":"Pseudo-translation","term":"伪翻译","pinyin":"Wěi Fānyì","definition":"在实际翻译之前用模拟译文测试UI布局的技术。可以用乱码文本或标记有长度特点的占位文本，检查UI是否能适应目标语言的长度变化。","definitionEn":"Using mock translated text to test UI layout before real translation.","example":"在实际翻译前进行伪翻译可以提前发现UI布局问题。","exampleEn":"Pseudo-translation before actual translation catches UI layout issues early.","category":"localization","tags":["UI测试","前置验证","布局检查"]},{"id":106,"front":"Darwin Information Typing Architecture (DITA)","term":"DITA","pinyin":"DITA","definition":"OASIS制定的XML架构，用于创建、生产和交付面向主题的技术内容。DITA内容易于本地化，因为它将内容分解为独立主题单元。","definitionEn":"OASIS XML architecture for creating topic-based technical content, which is easily localizable.","example":"技术文档公司普遍采用DITA来简化多语言本地化流程。","exampleEn":"Technical documentation companies widely use DITA to streamline multilingual localization.","category":"localization","tags":["XML","技术文档","主题化"]},{"id":107,"front":"SVG Localization","term":"SVG本地化","pinyin":"SVG Běndìhuà","definition":"可缩放矢量图形（SVG）中的文本本地化。SVG文本是可编辑的，比位图更适合本地化。但要注意字体嵌入、文字方向等问题。","definitionEn":"Localizing text in Scalable Vector Graphics—editable unlike bitmaps, but font embedding and text direction matter.","example":"产品图示使用SVG可以方便地进行多语言本地化。","exampleEn":"SVG product illustrations can be easily localized into multiple languages.","category":"localization","tags":["图片","矢量图","文本嵌入"]},{"id":108,"front":"Right-to-Left (RTL) Languages","term":"RTL语言","pinyin":"RTL Yǔyán","definition":"从右向左书写的语言，如阿拉伯语、希伯来语、乌尔都语等。本地化时UI需要水平翻转，同时保持某些元素（如数字）的从左向右显示。","definitionEn":"Languages written right-to-left: Arabic, Hebrew, Urdu. Localized UI must be horizontally flipped.","example":"支持RTL语言需要从设计阶段就考虑双向性（BiDi）。","exampleEn":"Supporting RTL languages requires Bidirectional (BiDi) support from the design stage.","category":"localization","tags":["双向性","阿拉伯语","希伯来语"]},{"id":109,"front":"Global Content Management System (GCMS)","term":"全球内容管理系统","pinyin":"Quánqiú Nèiróng Guǎnlǐ Xìtǒng","definition":"集中管理多语言内容的CMS系统，结合翻译工作流、内容存储、版本管理等功能。支持DITA、XLIFF等标准化格式。","definitionEn":"CMS systems managing multilingual content with translation workflows, content storage, and versioning.","example":"大型企业用GCMS来统一管理全球多语言网站内容。","exampleEn":"Large enterprises use GCMS to centrally manage global multilingual website content.","category":"localization","tags":["CMS","多语言","企业级"]},{"id":110,"front":"Linguistic Quality Assessment (LQA)","term":"LQA","pinyin":"LQA","definition":"语言质量评估，本地化测试的核心环节。评估译文的准确性、流畅性、风格、术语一致性、格式正确性等。通常使用MQM错误分类框架。","definitionEn":"Core of localization testing: assessing accuracy, fluency, style, terminology, formatting.","example":"LQA报告是翻译质量反馈的主要方式。","exampleEn":"LQA reports are the primary means of translation quality feedback.","category":"localization","tags":["质量评估","测试","本地化"]},{"id":120,"front":"Literary Translation","term":"文学翻译","pinyin":"Wénxué Fānyì","definition":"翻译文学作品（小说、诗歌、戏剧等）。核心是传达原作的美学价值和文学风格，而非仅仅传达内容。对译者的文学素养和语言表达能力要求极高。","definitionEn":"Translating literary works, focusing on aesthetic value and literary style, not just content.","example":"诗歌翻译常被认为是翻译的最高形式。","exampleEn":"Poetry translation is often considered the highest form of translation.","category":"written","tags":["文学","诗歌/小说","美学"]},{"id":121,"front":"Scientific and Technical Translation","term":"科技翻译","pinyin":"Kējì Fānyì","definition":"翻译科学技术领域的文本，如学术论文、专利说明书、产品手册、技术标准等。要求准确性和逻辑性，通常有大量专业术语。","definitionEn":"Translating scientific-technical texts: papers, patents, manuals, standards. Requires accuracy and logic.","example":"科技翻译的核心要求是术语准确和逻辑清晰。","exampleEn":"Sci-tech translation prioritizes terminology accuracy and logical clarity.","category":"written","tags":["专业翻译","术语","准确性"]},{"id":122,"front":"Legal Translation","term":"法律翻译","pinyin":"Fǎlǜ Fānyì","definition":"翻译法律领域的文本，如合同、判决书、法律条文、法律意见书等。要求极度准确，可能产生法律后果。通常需要译员具备法律专业知识。","definitionEn":"Translating legal texts: contracts, judgments, statutes. Extreme accuracy required—mistakes can have legal consequences.","example":"合同翻译中一个介词的选择可能影响整个条款的含义。","exampleEn":"A single preposition in contract translation can affect an entire clause\u0027s meaning.","category":"written","tags":["专业翻译","合同","法律后果"]},{"id":123,"front":"Medical Translation","term":"医学翻译","pinyin":"Yīxué Fānyì","definition":"翻译医学领域的文本，如病历、药品说明书、医学论文、临床试验文档等。对准确性要求极高，错误可能危及生命。通常需要双资质：翻译+医学背景。","definitionEn":"Translating medical texts with extreme accuracy requirements—errors can be life-threatening.","example":"药品说明书的翻译必须经过多重审校确保安全。","exampleEn":"Drug label translations must pass multiple review stages to ensure safety.","category":"written","tags":["专业翻译","高风险","双资质"]},{"id":124,"front":"Business Translation","term":"商务翻译","pinyin":"Shāngwù Fānyì","definition":"翻译商务领域的文本，如商业信函、会议纪要、年报、招股说明书等。要求正式规范的语言风格和准确的商务术语。","definitionEn":"Translating business texts: letters, meeting minutes, annual reports, IPO documents.","example":"年报翻译要特别关注财务术语的准确使用。","exampleEn":"Annual report translation must pay special attention to financial terminology.","category":"written","tags":["专业翻译","商务","正式"]},{"id":125,"front":"News Translation","term":"新闻翻译","pinyin":"Xīnwén Fānyì","definition":"翻译新闻报道、新闻稿、专栏文章等。要求准确传达信息和立场，同时保持新闻体的语言风格。注意中立性和客观性。","definitionEn":"Translating news reports: accuracy, news-style tone, neutrality.","example":"新闻翻译要保持客观中立，避免加入译者的主观倾向。","exampleEn":"News translation must maintain objectivity and avoid injecting translator bias.","category":"written","tags":["媒体","中立性","时效性"]},{"id":126,"front":"Patent Translation","term":"专利翻译","pinyin":"Zhuānlì Fānyì","definition":"翻译专利说明书、权利要求书等专利文件。对准确性和格式要求极高。\"权利要求书\"的翻译尤其关键，一字之差可能影响专利保护范围。","definitionEn":"Translating patent documents—\"claims\" are especially critical, as a single word difference can affect patent scope.","example":"专利翻译错误可能导致专利在目标国家失效。","exampleEn":"Patent translation errors can invalidate the patent in target countries.","category":"written","tags":["法律/科技交叉","高风险","权利要求"]},{"id":127,"front":"Subtitling","term":"字幕翻译","pinyin":"Zìmù Fānyì","definition":"为影视作品制作双语或目标语字幕。除了翻译内容，还需满足时间轴对齐、行数限制、字符限制、阅读速度等技术约束。","definitionEn":"Creating translated subtitles for video with timing, line, character, reading speed constraints.","example":"字幕翻译通常每行不超过35个字符，每屏停留4-6秒。","exampleEn":"Subtitling: usually max 35 chars per line, 4-6 seconds onscreen.","category":"written","tags":["影视","时间轴","技术约束"]},{"id":128,"front":"Dubbing","term":"配音翻译","pinyin":"Pèiyīn Fānyì","definition":"为影视作品制作目标语言的配音脚本。需精确匹配口型、语速、停顿、情绪等。比字幕翻译的限制更多。","definitionEn":"Creating dubbed scripts for video—must match lip movements, pace, pauses, emotions.","example":"好的配音翻译让观众感觉演员是在用中文说话。","exampleEn":"Good dubbing makes viewers feel actors are speaking Chinese.","category":"written","tags":["影视","口型匹配","表演性"]},{"id":129,"front":"Audio Description","term":"音频描述","pinyin":"Yīnpín Miáoshù","definition":"为视障人士提供的附加音轨，描述视频画面中的视觉元素。也是翻译的一种形式——将视觉信息转化为语言描述。","definitionEn":"Additional audio track describing visual elements for visually impaired viewers.","example":"音频描述翻译需要精确理解画面内容并用生动语言描述。","exampleEn":"Audio description translation requires precise understanding of visuals and vivid description.","category":"written","tags":["无障碍","视听","描述性"]},{"id":130,"front":"Localization Translation","term":"本地化翻译","pinyin":"Běndìhuà Fānyì","definition":"针对特定目标市场的翻译。不仅仅是语言转换，还要调整日期、货币、度量衡、格式、文化引用等。与单纯的\"翻译\"相比更强调市场适配。","definitionEn":"Translation adapted to a specific target market: dates, currencies, formats, cultural references.","example":"营销文案的本地化翻译要让目标市场的消费者产生共鸣。","exampleEn":"Marketing copy localization must resonate with target market consumers.","category":"written","tags":["市场","文化适配","L10n"]},{"id":140,"front":"Simultaneous Interpreting (SI)","term":"同传","pinyin":"Tóngshí Chuányì","definition":"讲话者持续发言的同时，译员几乎同步进行翻译。是难度最高的口译形式，译员需要一边听、一边翻、一边说。广泛用于国际会议。","definitionEn":"Interpreting while speaker continues—most demanding form. Used in international conferences.","example":"联合国大会的同传是口译员的最高舞台。","exampleEn":"UN General Assembly SI is the highest stage for interpreters.","category":"interpretation","tags":["高端","国际会议","高难度"]},{"id":141,"front":"Consecutive Interpreting (CI)","term":"交传","pinyin":"Jiāotì Chuányì","definition":"讲话者讲一段（通常5-10分钟），停一下让译员翻译。译员需要做笔记来辅助记忆。常用于商务谈判、记者会等场合。","definitionEn":"Speaker speaks 5-10 min, pauses for interpreter. Note-taking is essential.","example":"商务谈判中常用交传，因为需要双方充分沟通。","exampleEn":"Business negotiations often use CI for full two-way communication.","category":"interpretation","tags":["常规","笔记法","商务"]},{"id":142,"front":"Sight Interpretation/Sight Translation","term":"视译","pinyin":"Shìyì","definition":"看着书面文本（原文）进行的口头翻译。兼具口译和笔译的特点，常用于新闻发布会、政府会议等需要快速翻译的场合。","definitionEn":"Oral translation while reading written source text—combines interpretation and translation characteristics.","example":"外交官在新闻发布会上可能需要进行视译。","exampleEn":"Diplomats may need sight interpreting at press conferences.","category":"interpretation","tags":["书面+口头","快速","新闻"]},{"id":143,"front":"Whispered Interpreting (Chuchotage)","term":"耳语同传","pinyin":"Ěryǔ Tóngchuányì","definition":"在没有同传设备的情况下，译员坐在听众旁边，以耳语方式进行同传。通常只有1-2个听众。","definitionEn":"SI whispered to 1-2 listeners without equipment.","example":"小型会议中有时使用耳语同传代替设备同传。","exampleEn":"Small meetings sometimes use whispered interpreting instead of equipment-based SI.","category":"interpretation","tags":["小型","无设备","耳语"]},{"id":144,"front":"Relay Interpreting","term":"接力同传","pinyin":"Jiēlì Tóngchuányì","definition":"多语言同传模式。第一个译员把A语言译成通用语（如英语），第二个译员再把通用语译成C语言。用于讲话者语言不直接提供目标语言同传的场合。","definitionEn":"Multi-language SI chain: A→B→C via a relay language.","example":"当讲话者使用小语种时，通常采用接力同传。","exampleEn":"Relay interpreting is used when speakers use less common languages.","category":"interpretation","tags":["多语言","通用语","链式"]},{"id":145,"front":"Note-taking","term":"笔记法","pinyin":"Bǐjì Fǎ","definition":"交传译员使用的速记技术。用简洁的符号和缩写记录讲话的核心信息，而非逐字记录。是交传的核心技能。","definitionEn":"Consecutive interpreters\u0027 shorthand using concise symbols to capture core information.","example":"好的笔记法可以让译员准确回忆出十分钟讲话的全部要点。","exampleEn":"Good note-taking lets interpreters accurately recall all key points of a 10-minute speech.","category":"interpretation","tags":["交传核心","速记","记忆辅助"]},{"id":146,"front":"Working Memory","term":"工作记忆","pinyin":"Gōngzuò Jìyì","definition":"短时记忆的一种，是口译员最核心的认知能力。同传需要同时处理听辨、理解、转换、表达多个任务，对工作记忆要求极高。","definitionEn":"Core cognitive ability for interpreters—SI requires simultaneous listening, comprehension, conversion, and expression.","example":"同传译员的工作记忆容量通常大于普通人。","exampleEn":"SI interpreters typically have larger working memory capacity than average.","category":"interpretation","tags":["认知能力","核心技能","同传关键"]},{"id":147,"front":"Pre-interpreting Preparation","term":"译前准备","pinyin":"Yìqián Zhǔnbèi","definition":"口译活动前的准备工作，包括了解主题、学习相关术语、收集背景资料、熟悉讲话者风格等。充分的准备直接影响口译质量。","definitionEn":"Pre-event preparation: learning topic, terminology, background, speaker style.","example":"专业会议同传译员通常提前一到两周开始准备。","exampleEn":"Conference SI interpreters usually start preparing one to two weeks in advance.","category":"interpretation","tags":["会前","术语学习","背景研究"]},{"id":148,"front":"Interpreting Booth","term":"口译 booth","pinyin":"口译工作间","definition":"同传译员的专业工作间，通常是隔音的玻璃房间，配备耳机、麦克风、控制台等设备。译员在booth里听讲话者，通过麦克风输出译文。","definitionEn":"Soundproof glass booth for SI interpreters with headphones, mic, console.","example":"专业口译booth是会议同传的标配设备。","exampleEn":"Professional interpreting booths are standard equipment for conference SI.","category":"interpretation","tags":["设备","工作环境","同传"]},{"id":149,"front":"Number Interpreting","term":"数字口译","pinyin":"Shùzì Chuányì","definition":"口译中的数字处理，包括倍数、百分比、趋势、统计数据等。中英数字表达差异大（如万、亿 vs thousand, million, billion），是口译难点之一。","definitionEn":"Interpreting numbers—Chinese-English differences (wàn/yì vs thousand/million/billion) make this difficult.","example":"十亿到billion的转换需要瞬间完成，是口译的基本功。","exampleEn":"Converting shí yì to billion instantly is a fundamental interpreting skill.","category":"interpretation","tags":["数字","中英差异","基本功"]},{"id":150,"front":"Public Speaking Skills","term":"公众演讲","pinyin":"Gōngzhòng Yǎnjiǎng Jìnéng","definition":"优秀口译员需要的辅助技能，包括清晰的发音、适中的语速、自信的仪态、恰当的重音和停顿等。好的表达能让听众更易理解译文。","definitionEn":"Interpreter\u0027s ancillary skills: clear pronunciation, moderate pace, confident demeanor, appropriate stress and pauses.","example":"口译员的声音表达能力与翻译准确性同样重要。","exampleEn":"Interpreters\u0027 vocal expression matters as much as translation accuracy.","category":"interpretation","tags":["表达","自信","专业形象"]},{"id":160,"front":"Literal Translation Without Context","term":"望文生义","pinyin":"Wàngwén Shēngyì","definition":"只根据字面意思翻译而忽略真正含义的常见错误。如将英文\"marriage of convenience\"译为\"方便的婚姻\"（正确译为\"权宜婚姻\"）。","definitionEn":"Translating literally without understanding actual meaning. Example: \"marriage of convenience\" → wrong \"方便的婚姻\", correct \"权宜婚姻\".","example":"将\"black sheep\"译为\"黑羊\"就是典型的望文生义。","exampleEn":"Translating \"black sheep\" as \"black sheep\" instead of \"the odd one out\" is a classic example.","category":"errors","tags":["常见错误","成语/习语","理解偏差"]},{"id":161,"front":"Chinglish","term":"中式英语","pinyin":"Zhōngshì Yīngyǔ","definition":"将中文表达方式直接套用到英文中产生的不地道英语。如\"long time no see\"（虽然已成固定表达）、\"good good study, day day up\"等。也指翻译中过于忠实中文句法的生硬译文。","definitionEn":"Ungrammatical/unidiomatic English produced by directly transferring Chinese expressions.","example":"\"people mountain people sea\"应译为\"a sea of people\"而非直译。","exampleEn":"\"People mountain people sea\" should be \"a sea of people\", not a literal translation.","category":"errors","tags":["E-C翻译","不地道","中式"]},{"id":162,"front":"Translationese","term":"翻译腔","pinyin":"Fānyì Qiāng","definition":"译文带有明显翻译痕迹、读起来不自然的现象。如中译英时保留中文的流水句结构、滥用被动语态、逐字对应等。","definitionEn":"Translation with obvious trace of source language, reading unnaturally.","example":"翻译腔重的译文虽\"准确\"但读起来很累，需要编辑润色。","exampleEn":"Translationese, while \"accurate\", is tiring to read and needs editing.","category":"errors","tags":["E-C翻译","生硬","编辑"]},{"id":163,"front":"Over-translation / Under-translation","term":"增译/漏译","pinyin":"Zēngyì / Lòuyì","definition":"增加原文没有的内容（增译）或遗漏原文应有的信息（漏译）。增译和漏译在翻译中时有发生，需要有意识地避免。","definitionEn":"Adding content not in source (over-translation) or omitting necessary information (under-translation).","example":"不小心漏译一个\"不\"字可能完全颠倒原文意思。","exampleEn":"Accidentally omitting a \"not\" can completely reverse the original meaning.","category":"errors","tags":["信息偏差","准确性","遗漏/添加"]},{"id":164,"front":"Terminology Inconsistency","term":"术语不统一","pinyin":"Shùyǔ Bù Tǒngyī","definition":"同一翻译项目中，同一个专业术语被译成不同的目标语表达。严重影响译文质量，是大型翻译项目中常见的问题。可以通过术语库和QA检查避免。","definitionEn":"Same term translated differently within one project—seriously affects quality.","example":"在同一产品手册中，\"server\"不能一会儿译成\"服务器\"一会儿译成\"服务端\"。","exampleEn":"In a product manual, \"server\" must not be translated as both \"服务器\" and \"服务端\".","category":"errors","tags":["QA","术语库","大型项目"]},{"id":165,"front":"Numerical Error","term":"数字错误","pinyin":"Shùzì Cuòwù","definition":"翻译中出现的数字错误，如小数点错位、百分比误解、单位换算错误等。在财务、科技、医学翻译中可能导致严重后果。","definitionEn":"Mistakes with numbers: decimal point errors, percentage misunderstanding, unit conversion mistakes.","example":"将\"1.5 billion\"译为\"15亿\"而非\"15亿\"（1.5 billion = 15亿？不对，应该是15亿=1.5 billion，注意\"十亿\"的区别）。","exampleEn":"1.5 billion vs 15亿: both are correct, but 1.5 billion ≠ 1.5亿. Context matters.","category":"errors","tags":["数字","高风险","单位"]},{"id":166,"front":"Cultural Mistranslation","term":"文化误译","pinyin":"Wénhuà Wùyì","definition":"忽略文化差异导致的翻译错误。如将中国的\"龙\"（象征吉祥）译为英文的\"dragon\"（常指邪恶的龙），或反之。文化差异是翻译中最重要的问题之一。","definitionEn":"Mistranslation from ignoring cultural differences. Example: Chinese \"lóng\" (auspicious) vs English \"dragon\" (often evil).","example":"奥运会吉祥物\"福娃\"最初译\"Friendlies\"因有歧义后改为\"Fuwa\"。","exampleEn":"Olympic mascots were initially \"Friendlies\" but changed to \"Fuwa\" due to ambiguity.","category":"errors","tags":["文化","误解","典故"]},{"id":167,"front":"Formatting Error","term":"格式错误","pinyin":"Géshì Cuòwù","definition":"译文格式与原文不一致的问题。包括标点符号（如中英文标点混用）、数字格式（日期、货币单位）、缩进、字体、表格等。CAT工具可以自动检查部分格式问题。","definitionEn":"Formatting inconsistencies: mixed English-Chinese punctuation, date formats, currencies, etc.","example":"中文译文中误用英文标点或反之都是常见格式错误。","exampleEn":"Using English punctuation in Chinese translation or vice versa is a common error.","category":"errors","tags":["格式","标点","QA"]},{"id":168,"front":"Missing/Misplaced Tags","term":"漏翻标签","pinyin":"Lòufān Biāoqiān","definition":"本地化翻译中未正确保留或放置HTML标签、CAT标记代码等格式标签。可能导致UI错乱、链接失效、样式丢失等。CAT工具的QA功能可以自动检查。","definitionEn":"Failure to preserve HTML/CAT tags correctly in localization, causing UI breaks or style loss.","example":"译文中漏掉一个\u003cbr\u003e标签会导致UI上本应换行的文本挤在一起。","exampleEn":"Missing \u003cbr\u003e tags cause text that should wrap to crowd together in the UI.","category":"errors","tags":["本地化","技术错误","QA"]},{"id":169,"front":"Over-literal Technical Term","term":"术语过度直译","pinyin":"Shùyǔ Guòdù Zhíyì","definition":"技术术语生硬直译但不符合目标语言专业领域习惯的译法。如将\"deadlock\"（计算机锁死）译成\"死亡锁\"而非标准的\"死锁\"。","definitionEn":"Literal translation of technical terms that don\u0027t match target language professional conventions.","example":"\"deadlock\"在计算机领域应译为\"死锁\"而非\"死亡锁\"。","exampleEn":"In computing, \"deadlock\" should be \"死锁\", not \"死亡锁\".","category":"errors","tags":["术语","科技","行业惯例"]},{"id":170,"front":"Misused Machine Translation","term":"机器翻译误用","pinyin":"Jīqì Fānyì Wùyòng","definition":"过度依赖机器翻译而不进行充分的人工作业。尤其是文学翻译、法律翻译、营销翻译等需要创造力和精确判断力的领域，MT输出通常不可直接使用。","definitionEn":"Over-reliance on MT without sufficient human review, especially in creative or high-accuracy fields.","example":"直接用谷歌翻译翻译法律合同可能导致严重错误。","exampleEn":"Using Google Translate directly for legal contracts can cause serious errors.","category":"errors","tags":["MT风险","质量","过度依赖"]}]};